DataValueDWORD g_aDefineData_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS[] =
{
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_SAMPLES_FROM_FILE, 0x0004 , "Do not use our default patterns but get the sample positions from a file specified in MAXWELL_B_FRAME_SAMPLE_POSITION_INTERLEAVE_PATH" },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_DISABLE_ON_SQUARE_TARGETS, 0x0008 , "Disable the effect on square rendertargets, the rationale being they might be used to encode shadow maps" },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_DISABLE_DITHERING, 0x0010 , "Some games are incompatible with a sample pattern that varies per pixel position. So disable this for this game" },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_DECOMPRESS_DEPTH_ON_TEXTURE_READ, 0x0020 , "L2 from texture is unable to interpret non standard sample positions for depth, so we need to decompress them on the fly before that texture read happens. No need to enable if corruption is not visible." },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_DISABLE_ON_DENY_LISTED_RATIOS, 0x0040 , "Disable the effect on rendertargets/z-buffers of certain ratios (1:1, 2:1, 3:1, 4:1, 1:2, 1:3 and 1:4), the rationale being they might be used to encode shadow maps" },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_ALLOW_ONLY_ON_ALLOWLISTED_RATIOS, 0x0200 , "Enable the effect only on surfaces that are of the same aspect ratio as the backbuffer. This can be used to avoid applying interleaving on shadowmaps for games where DISABLE_ON_DENY_LISTED_RATIOS doesn't work." },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_ALLOW_ON_BIGGER_THAN_BACK_BUFFER, 0x0400 , "when ALLOW_ONLY_ON_ALLOWLISTED_RATIOS is set, by default interleaving is disabled on surfaces bigger than the backbuffer. Set this key to enable it for such surfaces that have same aspect ratio as backbuffer but are bigger. This setting has no effect if ALLOW_ONLY_ON_WHITELISTED_RATIOS isn't set." },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_IGNORE_APP_PROFILE, 0x1000 , "if MAXWELL_B_SAMPLE_INTERLEAVE is ON and there is no app profile associated with the current executable, apply the effect nonetheless, used for testing purpose" },
    { (const char **)g_ppszDefineDataNames_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS_PATCH_ATTRIBUTE_EVAL_OFFSETS, 0x4000 , "Always evaluating the attributes at pixel center causes corruptions with some games when run with MFAA and without MSAA. Setting this bit causes the driver to replace all IPA instructions with IPA.offset when the shader is used without MSAA which ensures the attribute evaluation happens at the same location as the jittered raster sample position." },
};

DataDefaultDWORD g_aDefaultData_MAXWELL_B_SAMPLE_INTERLEAVE_SETTINGS[] =
{
    {"DEFAULT", 0x00001040, "DISABLE_ON_DENY_LISTED_RATIOS | IGNORE_APP_PROFILE" }, 
};

