DataValueDWORD g_aDefineData_MCAPPSPECIFICHACKS10[] =
{
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_NONE, 0x00000000 , "the default value, no app specific hacks" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_NOT_DISCARD_ON_SCREENSIZE_A2B10G10R10_RTT, 0x00000001 , "Respect sync on screensize A2B10G10R10 RTT, Dirt: Showdown specific hack" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_SKIP_TINY_TEXTURE_RESOLVE_ON_BLITTING, 0x00000002 , "Ignore small texture (up to 2x2) resolve on blit, Stormrise specific hack" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_FORCE_RESOLVE_ON_SECONDARY_GPU_FOR_SHARED_RESOURCES, 0x00000004 , "Force resolve on secondary GPUs for shared resources, specific for Lucas Arts Hive Engine Demo" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_IGNORE_READ_LOCK_FOR_STAGING_TEXTURES, 0x00000008 , "Ignore CPU read lock for staging textures - real hack, specific to Red Faction: Armageddon" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_EARLY_PUSH_ALL_SUBRESOURCES, 0x00000010 , "Defer early push of subresources with hope that we can early push the entire resource" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_SKIP_NOSUBRES_RTT_BUT_TINY_RESOLVE_ON_TEXTURING, 0x00000020 , "don't resolve textures before texturing unless they are tiny (2x2), but respect resolve for resources with subresources" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_CRYSIS2_HACK_POSTMSAAEDGEFILTERNV_OVERRIDE, 0x00000040 , "Fix up Crysis2 binary to be consistent with SLI" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_NOT_DISCARD_SMALL_COMPUTE, 0x00000080 , "Avoid discarding small compute resources (under 4kB)" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_FORCE_REPORT_NO_SLI_SUPPORT_FROM_NVAPI, 0x00000100 , "If application has buggy its own SLI support we need to do SLI magic in the driver and force app think it's run on single GPU" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_NOT_DISCARD_ON_MIDSIZE_TEXTURE_ABGR8_RTT, 0x00000200 , "Syncs on ABGR8 RTT or on any RTTs with 0x100X0x100 size,COD:BO2 fetches Online status of player" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_TEXTURING_AFTER_BLIT_FOR_SCREENSIZE_RTT, 0x00000400 , "Discard sync on screensize RTT if texturing happen after blit into" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_COMPUTE_1D, 0x00000800 , "Discard content of compute (like DISCARD_ON_COMPUTE bit) only for 1-dimensional resources" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_FC_GPULT_BG, 0x00001000 , "Force load balancing to GPU_LIMITED if bridgeless is in action, AvP" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_RESOURCES_WITH_SUBRESOURCES_GPU_COUNT, 0x00002000 , "Discard GFX resolve on RTTs with subresources (cube/mip mapped) after nAFR GPU attempt to bind it as texture" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_ACIV_LOCK_WAR, 0x00004000 , "Assassins Creed: BF MP WAR. Requires 0x8 be set. Granted read lock on staging RTT ABGR8 0x60/0x60 or 0x200/0x200" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_ALLOW_P2P_FOR_COMPRESSED_TEXTURES, 0x00008000 , "Application could use GPU for compress textures, it happens in unicast and final compressed texture becomes dirty on non-active GPUs. as result we need to sync such textures, but use P2H2P instead of more fast P2P. This bit allowed P2P for such cases." },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_RESPECT_SYNCS_FROSTBITE_SPECIFIC, 0x00010000 , "SW:BF and possible other Frostbite 3+ based games requires specific syncs to handle temporal AAs/AO  and cubemap updates properly, this bit is about these syncs, also respect sync for decal VBs" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_SYNC_ON_BIND_FOR_SQUARE_TYPELESS_R8_R32_BGRA8_RTT, 0x00020000 , "Respects sync on bind for square RTTs with B8G8R8A8, R8 and R32 TYPELESS format, hack for broken texture streaming in Elite Dangerous" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_NOT_REPORT_SLI_FOR_MOSAIC_UNTIL_IN_AFR, 0x00040000 , "Do not report SLI to the app until in AFR. Trust the App that it will query SLI state again on switching to fullscreen and won't disable it's SLI features based on the initial values returned. Hack for hung Elite Dangerous" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_SYNC_ON_BIND_FOR_SQUARE_ABGR16F_0x100__RTT, 0x00080000 , "Respect sync on bind for 0x100/0x100 ABGR16F RTT. The app has bind/unbind it rarely and discard on bind in AFR2 key kept it discarded wrongly. Hack for Mad Max" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_ALLOW_BF1_SYNCS, 0x00100000 , "Allow sync of a few specific resources in BF1 Frostbite engine to fix some flickering" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_SYNC_ON_BIND_FOR_3D_RTT, 0x00200000 , "Do sync on bind for  3D textures (depth >1), this WAR needed for fog of war corruption fix in XCOM2" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_SYNC_ON_BIND_FOR_SQUARE_RGBA_ABGR_0x100_0x200_RTT, 0x00400000 , "Do sync on bind for square RTTs with A8B8G8R8, R8G8B8A8 formats, and 0x100/0x200 width, WAR to fix corruption with Dark Souls 3" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_R11G11B10_FLOAT_RT, 0x00800000 , "Discard content of R11G11B10_FLOAT RT, DiRT 4 specific hack" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_ALLOW_RFTA_SYNCS, 0x01000000 , "Allow sync of a few specific resources in Remnant From The Ashes to avoid corruption" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_NVAPI_SYNC_FOR_SCREENSIZE_RTT, 0x02000000 , "Discard primary size resolves from beginEndResourceRendering, Starlink specific hack" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_RESPECT_PRIMARY_DISCARD_ON_PRESENT, 0x04000000 , "Discard primary surface if and only if it has DISCARD_ON_PRESENT flag (for 3DMark)" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISABLE_COPY_TRACKER_SWAPPING, 0x08000000 , "Disable swapping of redirected resources in CopyTracker in AFR" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DO_SYNC_ON_SCREENSIZE_R11G11B10_FLOAT, 0x10000000 , "Sync screen size resources of type R11G11B10_FLOAT" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_DISCARD_ON_NVAPI_SYNC_FOR_SQUARE_RTT_0x400, 0x20000000 , "Discard 0x400 x 0x400 size resolves from beginEndResourceRendering" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_ALLOW_JWE_SYNCS, 0x40000000 , "Allow sync of a few specific resources in Jurassic World Evolution to fix some flickering" },
    { (const char **)g_ppszDefineDataNames_MCAPPSPECIFICHACKS10_RESERVED31, 0x80000000 , "Reserved" },
};

